import { readFileSync } from 'node:fs'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import { buildIndex } from '../../scripts/build-law-concepts'

const ROOT = path.resolve(__dirname, '../..')
const SHIPPED = path.join(ROOT, 'worker/src/law-concepts.json')

/**
 * The worker's copy of law -> concept, held to the corpus it was taken from.
 *
 * The worker carries no corpus, so the roster resolves a concept from a
 * generated file. Nothing at runtime can notice that file going stale: a law
 * added to the corpus after the last generation simply renders with no concept
 * beside it, which a partner reads as "they do not know what this card is
 * about" rather than as a build step somebody forgot. This is the only thing
 * that can tell the difference.
 */
describe('the worker’s law index', () => {
  it('names a concept for every law in every corpus, and no law that is gone', () => {
    const shipped = JSON.parse(readFileSync(SHIPPED, 'utf8'))
    expect(shipped).toEqual(buildIndex(ROOT))
  })

  it('is regenerated byte for byte, so a diff shows only laws that changed', () => {
    // Key order and formatting are part of the contract: a regeneration that
    // reordered the file would put 1028 lines in a diff and hide the one line
    // that mattered.
    expect(readFileSync(SHIPPED, 'utf8')).toBe(`${JSON.stringify(buildIndex(ROOT), null, 2)}\n`)
  })
})
